export interface StorageVariant {
  storage: string;   // e.g. "128GB"
  priceAdder: number; // ZMW added on top of user's base price (0 = base tier)
}

export interface CatalogPhone {
  id: string;
  brand: string;
  model: string;
  name: string;
  imageUrl: string;          // GSMArena CDN — graceful 404 fallback in UI
  storageVariants: StorageVariant[];
  category: "phones";
}

// ─── Storage tiers ────────────────────────────────────────────────────────────
// priceAdder values are in ZMW — user's base price is for the first variant
const TIERS = {
  ultraBudget:  [{ storage:"32GB",  priceAdder:0 }, { storage:"64GB",  priceAdder:150 }],
  budget:       [{ storage:"64GB",  priceAdder:0 }, { storage:"128GB", priceAdder:250 }],
  midRange:     [{ storage:"128GB", priceAdder:0 }, { storage:"256GB", priceAdder:500 }],
  upperMid:     [{ storage:"128GB", priceAdder:0 }, { storage:"256GB", priceAdder:600 }, { storage:"512GB", priceAdder:1200 }],
  flagship:     [{ storage:"256GB", priceAdder:0 }, { storage:"512GB", priceAdder:1000 }, { storage:"1TB", priceAdder:2000 }],
  ultraFlag:    [{ storage:"512GB", priceAdder:0 }, { storage:"1TB",   priceAdder:1500 }],
};

